CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,telegram_id TEXT UNIQUE NOT NULL,username TEXT,display_name TEXT,points BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS collections(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,variant TEXT,value NUMERIC(18,2) DEFAULT 0,image TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_collections(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,collection_id BIGINT REFERENCES collections(id) ON DELETE CASCADE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS transactions(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,amount BIGINT NOT NULL,description TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
